--- lua:
local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")

---@type Queue
local Queue = import("Game.DreamSpace.Tools.Queue")
local Time = CS.UnityEngine.Time
local Vector3 = CS.UnityEngine.Vector3
local Mathf = CS.UnityEngine.Mathf

---@class Track
local Track = Class("Track")



function Track:__init( trackIdx_, moveSpeed_, recycleDis_, trackSegments_, onSegmentRefresh_, othDatas_ )
    self.trackIdx = trackIdx_ -- 1,2,3
    self.moveSpeed = moveSpeed_
    ---@type Queue
    self._segmentQueue = Queue.New(#trackSegments_)
    self.trackSegments = trackSegments_
    self.recycleDis = recycleDis_ or 10 -- 触发 trackSegment 回收复用的距离(米)
    self.onSegmentRefresh = onSegmentRefresh_
    self.othDatas = checkTable(othDatas_) -- 任意自定义数据
    self:_InitSegments(trackSegments_)

    self.moveDistance = 0
    self.direction = 1     -- 选关界面中存在 倒退运动...
end

function Track:__delete()
    CoStop(self.co_1)
    self._segmentQueue:Clear()
    self._segmentQueue = nil
    for _, trackSegment in ipairs(self.trackSegments) do
        trackSegment:Delete()
    end
    self.trackSegments = nil
    self.onSegmentRefresh = nil
end

function Track:Reset()
    self._segmentQueue:Clear()
    self.moveDistance = 0
    for _, trackSegment in ipairs(self.trackSegments) do
        trackSegment:Reset()
    end
    self:_InitSegments(self.trackSegments)
end


function Track:SetSpeed(moveSpeed_)
    self.moveSpeed = moveSpeed_
end


---@param trackSegments TrackSegment[]
function Track:_InitSegments(trackSegments_)
    for i, trackSegment in ipairs(trackSegments_) do
        trackSegment.segmentIndex = i -- 1 based
        if i == 1 then
            trackSegment:SetPos(0)
        else
            trackSegment:SetPos(trackSegments_[i-1]:GetEndPosition())
        end
        self:_RefreshSegmentContent(trackSegment,i)
        self._segmentQueue:AddLast(trackSegment)
    end
end


function Track:Tick(deltaTime_)
    local moveDis = deltaTime_ * self.moveSpeed
    for _, trackSegment in ipairs(self.trackSegments) do
        if trackSegment.Tick then
            trackSegment:Tick(deltaTime_)
        end
    end
    self:Move(moveDis)
end


function Track:Move(distance_,direction_)
    if direction_ then
        self.direction = direction_ > 0 and 1 or -1
    end
    
    distance_ = distance_ * self.direction * self.moveSpeed * 0.2 -- todo: 这么写只是因为 track3 的移动速度默认为 5

    for _, trackSegment in ipairs(self.trackSegments) do
        trackSegment:Move(-distance_)
    end
    self.moveDistance = self.moveDistance + distance_
    self:_CheckOutRange()
end


function Track:MoveTime(time_, direction_)
    self.direction = direction_ > 0 and 1 or -1

    ---
    CoStop(self.co_1)
    self.co_1 = CoStart(function()
        while time_ > 0 do
            local deltaTime = Time.deltaTime
            self:Tick(deltaTime)
            time_ = time_ - deltaTime
            coroutine.yield(Yielders.EndOfFrame)
        end
    end)
end


function Track:_CheckOutRange()
    while true do
        ---@type TrackSegment
        local firstSegment = self._segmentQueue:PeekFirst()
        local lastSegment = self._segmentQueue:PeekLast()

        if self.direction > 0 and firstSegment:GetEndPosition() < -self.recycleDis then -- 向右

            --self:DebugPrint("向右, 回收", 3, true)

            firstSegment:SetPos(lastSegment:GetEndPosition())
            firstSegment.segmentIndex = lastSegment.segmentIndex + 1
            firstSegment:OnOutRange()
            self:_RefreshSegmentContent( firstSegment, firstSegment.segmentIndex )
            self._segmentQueue:AddLast(self._segmentQueue:RemoveFirst())

        elseif self.direction < 0 and firstSegment:GetStartPosition() > -self.recycleDis then -- 向左
            

            lastSegment:SetPos(firstSegment:GetStartPosition() - lastSegment.length)
            lastSegment.segmentIndex = firstSegment.segmentIndex - 1
            lastSegment:OnOutRange()
            self:_RefreshSegmentContent( lastSegment, lastSegment.segmentIndex )
            self._segmentQueue:AddFirst(self._segmentQueue:RemoveLast())

        else
            break
        end
    end
end



function Track:_RefreshSegmentContent(newSegment_,newSegmentIndex_)
    if self.onSegmentRefresh then
        self.onSegmentRefresh(newSegment_, newSegmentIndex_, self.othDatas)
    else
        newSegment_:RefreshContent()
    end
end




-- just for debug
function Track:DebugPrint( msg_, trackIdx_, isError_ )
    if isNull(trackIdx_) then 
        trackIdx_ = 3
    end 
    if self.trackIdx == trackIdx_ then 
        if isError_ == true then 
            printError(msg_)
        else 
            print(msg_)
        end 
    end
end




return Track
